// Some portions generated by Claude
/**
 * Which resources the explorer asks the repository about (labels, types), in what order and in what portions. Every
 * resource of the graph is looked up, however large the graph: the ones the canvas draws, and draws in view, first.
 */
import { RDF_TYPE } from "./graph-canvas-scope.ts";
import { findBindingValue } from "./graph-terms.ts";
import type { Graph, GraphEdge, GraphNode, GraphNodeType, GraphTransform } from "./graph-types.ts";
import { isQueryableResource, isSafeSparqlIri, sparqlNodeId } from "./rdf-terms.ts";
import type { SparqlTerm } from "./rdf-terms.ts";
import { GENERIC_TYPES, NODE_TYPE_LIMIT } from "./rdf-vocabulary.ts";

export type WorldBounds = { left: number; top: number; right: number; bottom: number };

export type LookupPriority = {
  /** The node whose details card is open. */
  focusedId?: string | null;
  /** The nodes the canvas draws; without it every node counts as drawn. */
  drawnIds?: ReadonlySet<string>;
  /** The part of the graph in view, in graph coordinates. */
  view?: WorldBounds | null;
};

/** The part of the graph a `width` × `height` viewport shows at `transform`, in graph coordinates. */
export function viewBounds(transform: GraphTransform, width: number, height: number): WorldBounds {
  return {
    left: -transform.x / transform.k,
    top: -transform.y / transform.k,
    right: (width - transform.x) / transform.k,
    bottom: (height - transform.y) / transform.k,
  };
}

function inView(node: GraphNode, view: WorldBounds | null | undefined) {
  return Boolean(view) && node.x !== undefined && node.y !== undefined &&
    node.x >= view!.left && node.x <= view!.right && node.y >= view!.top && node.y <= view!.bottom;
}

/**
 * The queryable resources among `nodes` that `wanted` accepts, each once: the focused node, drawn nodes in view, other
 * drawn nodes, then the rest, each group in graph order.
 */
export function lookupOrder(
  nodes: readonly GraphNode[],
  priority: LookupPriority,
  wanted: (node: GraphNode) => boolean = () => true,
): string[] {
  const focused: string[] = [];
  const shown: string[] = [];
  const drawn: string[] = [];
  const rest: string[] = [];
  const seen = new Set<string>();
  for (const node of nodes) {
    if (seen.has(node.id) || !wanted(node) || !isQueryableResource(node.id)) continue;
    seen.add(node.id);
    if (node.id === priority.focusedId) focused.push(node.id);
    else if (!priority.drawnIds || priority.drawnIds.has(node.id)) (inView(node, priority.view) ? shown : drawn).push(node.id);
    else rest.push(node.id);
  }
  return focused.concat(shown, drawn, rest);
}

/** The terms whose labels the graph shows: its predicates, the types of its nodes, then every resource (lookupOrder). */
export function labelLookupIds(graph: Graph, priority: LookupPriority): string[] {
  const ids = new Set<string>();
  for (const edge of graph.edges) ids.add(edge.predicate);
  for (const node of graph.nodes) for (const type of node.types ?? []) ids.add(type.id);
  for (const id of lookupOrder(graph.nodes, priority)) ids.add(id);
  return [...ids];
}

/**
 * Label lookups go in portions, so the first labels (the drawn nodes' ones) are applied while the rest still load:
 * on a graph of 50,000 resources, waiting for all of them would leave every label out for minutes.
 */
export const LABEL_CHUNKS = { first: 1000, rest: 4000 };

/**
 * Resolves `ids` portion by portion, in order, calling `onChunk` after each one. A failed portion does not stop the
 * others; the result says whether every portion succeeded. An abort stops it before the next portion.
 */
export async function resolveInChunks(
  ids: readonly string[],
  resolve: (chunk: string[], signal?: AbortSignal) => Promise<unknown>,
  onChunk: () => void,
  signal?: AbortSignal,
  sizes = LABEL_CHUNKS,
): Promise<boolean> {
  let complete = true;
  for (let start = 0; start < ids.length; ) {
    if (signal?.aborted) return false;
    const size = start === 0 ? sizes.first : sizes.rest;
    const chunk = ids.slice(start, start + size);
    start += size;
    try {
      await resolve(chunk, signal);
    } catch {
      complete = false;
    }
    if (signal?.aborted) return false;
    onChunk();
  }
  return complete;
}

/**
 * Resolves labels as resolveInChunks does, and remembers in `retries` the ids a failure left without an answer, a
 * whole portion or a batch of one (`unresolved` says which ids still have none): they are asked again once their wait
 * is over (LookupRetries.due), not only when the graph next changes, and a failure never counts as "no label". Ids
 * still waiting are left to that retry. `onChunk` gets the ids each portion left without an answer. Returns whether
 * every id has its answer; a cancelled lookup records nothing.
 */
export async function resolveLabels(
  ids: readonly string[],
  resolve: (chunk: string[], signal?: AbortSignal) => Promise<unknown>,
  unresolved: (ids: readonly string[]) => string[],
  retries: LookupRetries,
  now: () => number,
  onChunk: (failed: readonly string[]) => void,
  signal?: AbortSignal,
  sizes = LABEL_CHUNKS,
): Promise<boolean> {
  const started = now();
  const asked = ids.filter((id) => !retries.waiting(id, started));
  let complete = asked.length === ids.length;
  let failed: string[] = [];
  const resolved = await resolveInChunks(asked, async (chunk, chunkSignal) => {
    failed = [];
    try {
      await resolve(chunk, chunkSignal);
    } finally {
      if (!signal?.aborted) {
        failed = unresolved(chunk);
        const unanswered = new Set(failed);
        retries.succeeded(chunk.filter((id) => !unanswered.has(id)));
        retries.failed(failed, now());
        if (failed.length) complete = false;
      }
    }
  }, () => onChunk(failed), signal, sizes);
  return resolved && complete && !signal?.aborted;
}

/** The types each resource's loaded rdf:type statements state (withLoadedTypes gives them to the nodes at once). */
export function statedTypes(edges: readonly GraphEdge[]): Map<string, Set<string>> {
  const stated = new Map<string, Set<string>>();
  for (const edge of edges) {
    if (edge.predicate !== RDF_TYPE) continue;
    const types = stated.get(edge.source);
    if (types) types.add(edge.target);
    else stated.set(edge.source, new Set([edge.target]));
  }
  return stated;
}

/**
 * A resource whose types are still to be looked up: it has none yet, or it may have only those its loaded rdf:type
 * statements state (`stated`, see statedTypes) and no lookup has answered for it (typesLookedUp). A saved graph does
 * not keep typesLookedUp, so such a node is asked once more after a reload; a node with a type no loaded statement
 * states got it from a lookup.
 */
export function needsTypes(node: GraphNode, stated?: ReadonlyMap<string, ReadonlySet<string>>) {
  if (node.kind === "literal" || node.typesLookedUp || !isQueryableResource(node.id)) return false;
  if (node.types === undefined) return true;
  const loaded = stated?.get(node.id);
  return loaded !== undefined && node.types.every((type) => loaded.has(type.id));
}

/**
 * How many nodes a type lookup asks for after `completedRounds` rounds: small at first, so the first nodes get their
 * colours quickly, then larger, so a large graph needs few rounds (each one redraws the graph).
 */
export function typeRoundSize(completedRounds: number) {
  return Math.min(1280, 40 * 2 ** Math.min(completedRounds, 5));
}

/**
 * The nodes of the next type lookup: the focused node alone while it still needs types (its details card waits for
 * them), otherwise up to `size` nodes in lookupOrder. Nodes `waiting` to retry a failed lookup are left for later;
 * `stated` holds the types loaded rdf:type statements state (needsTypes).
 */
export function nextTypeRound(
  nodes: readonly GraphNode[],
  priority: LookupPriority,
  size: number,
  waiting: (id: string) => boolean,
  stated?: ReadonlyMap<string, ReadonlySet<string>>,
): string[] {
  const wanted = (node: GraphNode) => needsTypes(node, stated) && !waiting(node.id);
  const focused = priority.focusedId ? nodes.find((node) => node.id === priority.focusedId) : undefined;
  if (focused && wanted(focused)) return [focused.id];
  return lookupOrder(nodes, { ...priority, focusedId: null }, wanted).slice(0, size);
}

/**
 * A node's types, the most informative first: specific classes before generic ones (owl:Thing and the like say
 * nothing about a resource), then by label. The first one gives the node its colour.
 */
export function orderNodeTypes(types: readonly GraphNodeType[]): GraphNodeType[] {
  return [...types].sort(
    (left, right) =>
      Number(GENERIC_TYPES.includes(left.id)) - Number(GENERIC_TYPES.includes(right.id)) ||
      left.label.localeCompare(right.label) ||
      (left.id < right.id ? -1 : left.id > right.id ? 1 : 0),
  );
}

/**
 * The types of each node of a lookup (typesQuery rows), ordered by orderNodeTypes. Every node asked for gets a list:
 * an empty one when the repository has no type for it. At most NODE_TYPE_LIMIT types are kept, as the query asks.
 */
export function typesFromBindings(
  nodeIds: readonly string[],
  bindings: ReadonlyArray<Record<string, SparqlTerm | undefined>>,
  labelOf: (id: string) => string,
): Map<string, GraphNodeType[]> {
  const found = new Map(nodeIds.map((nodeId) => [nodeId, new Map<string, GraphNodeType>()]));
  for (const binding of bindings) {
    const node = findBindingValue(binding, ["node"]);
    const type = findBindingValue(binding, ["type"]);
    if (!node || !type || type.type !== "uri" || !isQueryableResource(sparqlNodeId(node)) || !isSafeSparqlIri(type.value))
      continue;
    const suppliedLabel = findBindingValue(binding, ["typeLabel", "classLabel"])?.value;
    found.get(sparqlNodeId(node))?.set(type.value, {
      id: type.value,
      labelInput: suppliedLabel ?? null,
      label: suppliedLabel && suppliedLabel !== type.value ? suppliedLabel : labelOf(type.value),
    });
  }
  return new Map(
    [...found].map(([nodeId, types]) => [nodeId, orderNodeTypes([...types.values()]).slice(0, NODE_TYPE_LIMIT)]),
  );
}

/** How long a lookup that failed `failures` times in a row waits before it is asked again: 5 s, 15 s, … up to 5 min. */
export function retryDelay(failures: number) {
  return Math.min(300_000, 5_000 * 3 ** Math.max(0, failures - 1));
}

/** Resources whose lookup failed (a timeout, a server error) and when each may be asked again. */
export class LookupRetries {
  private entries = new Map<string, { failures: number; retryAt: number }>();
  failed(ids: readonly string[], now: number) {
    for (const id of ids) {
      const failures = (this.entries.get(id)?.failures ?? 0) + 1;
      this.entries.set(id, { failures, retryAt: now + retryDelay(failures) });
    }
  }
  succeeded(ids: readonly string[]) {
    for (const id of ids) this.entries.delete(id);
  }
  /** The resources whose wait is over at `now`: the ones to ask again. */
  due(now: number): string[] {
    const due: string[] = [];
    for (const [id, { retryAt }] of this.entries) if (retryAt <= now) due.push(id);
    return due;
  }
  waiting(id: string, now: number) {
    const entry = this.entries.get(id);
    return entry !== undefined && entry.retryAt > now;
  }
  /** The earliest time after `after` at which a failed lookup may be asked again; undefined when none waits. */
  nextRetryAt(after = -Infinity): number | undefined {
    let next: number | undefined;
    for (const { retryAt } of this.entries.values())
      if (retryAt > after && (next === undefined || retryAt < next)) next = retryAt;
    return next;
  }
}

const isAbort = (error: unknown) => error instanceof DOMException && error.name === "AbortError";

/**
 * Looks up the types of `ids` with `load`. A failure is not an answer: it returns null, and `retries` keeps the nodes
 * from being asked again until their wait is over, so their types stay unknown ("Type loading") instead of becoming
 * "No type". A cancelled lookup returns null and is no failure.
 */
export async function lookupTypes(
  ids: readonly string[],
  load: (ids: string[], signal?: AbortSignal) => Promise<Map<string, GraphNodeType[]>>,
  retries: LookupRetries,
  now: () => number,
  signal?: AbortSignal,
): Promise<Map<string, GraphNodeType[]> | null> {
  try {
    const types = await load([...ids], signal);
    if (signal?.aborted) return null;
    retries.succeeded(ids);
    return types;
  } catch (error) {
    if (signal?.aborted || isAbort(error)) return null;
    retries.failed(ids, now());
    return null;
  }
}

/**
 * A node's `known` types (the ones its loaded rdf:type statements state) and the `found` ones of a lookup, each once
 * (a known one keeps its entry), ordered by orderNodeTypes and at most NODE_TYPE_LIMIT of them, as a lookup keeps them.
 */
export function mergeNodeTypes(known: readonly GraphNodeType[], found: readonly GraphNodeType[]): GraphNodeType[] {
  const byId = new Map(known.map((type) => [type.id, type]));
  for (const type of found) if (!byId.has(type.id)) byId.set(type.id, type);
  return orderNodeTypes([...byId.values()]).slice(0, NODE_TYPE_LIMIT);
}

/**
 * The graph with looked-up types on the nodes no lookup has answered for yet, merged with the types they have
 * (mergeNodeTypes) and marked typesLookedUp; the same graph when nothing changes.
 */
export function applyNodeTypes(graph: Graph, types: ReadonlyMap<string, GraphNodeType[]>): Graph {
  let changed = false;
  const nodes = graph.nodes.map((node) => {
    const discovered = types.get(node.id);
    if (!discovered || node.typesLookedUp || node.kind === "literal") return node;
    changed = true;
    return { ...node, types: mergeNodeTypes(node.types ?? [], discovered), typesLookedUp: true };
  });
  return changed ? { ...graph, nodes } : graph;
}
